import{_ as a,c as r,o,ag as i}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1791309864000}'),t={name:"guide/privacy.md"};function n(s,e,l,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p>nPlyr is a native video player for macOS and iOS. Your privacy is our priority.</p><h2 id="local-first-design" tabindex="-1">Local-First Design <a class="header-anchor" href="#local-first-design" aria-label="Permalink to &quot;Local-First Design&quot;">​</a></h2><ul><li>Your watch history, bookmarks and downloads are stored <strong>entirely on your device</strong>.</li><li>The app requires <strong>no account and no registration</strong>.</li><li>There is <strong>no telemetry</strong> — nPlyr does not phone home with usage data.</li><li>Core playback and downloads work fully offline once the media is on your device.</li></ul><h2 id="network-use-is-user-directed" tabindex="-1">Network Use Is User-Directed <a class="header-anchor" href="#network-use-is-user-directed" aria-label="Permalink to &quot;Network Use Is User-Directed&quot;">​</a></h2><p>nPlyr only uses the network when <em>you</em> ask it to:</p><ul><li>Streaming or downloading a video you opened or captured.</li><li>Browsing with the built-in sniffer.</li><li>Running a mini-program / rule source that you imported.</li></ul><p>We do not operate a server that receives your media, history or mini-program variables.</p><h2 id="the-browser" tabindex="-1">The Browser <a class="header-anchor" href="#the-browser" aria-label="Permalink to &quot;The Browser&quot;">​</a></h2><p>The built-in browser is a standard <code>WKWebView</code>. It does not inject trackers of its own. Cookies and local storage stay in the app&#39;s container, just like any other browser.</p><h2 id="mini-program-data" tabindex="-1">Mini-Program Data <a class="header-anchor" href="#mini-program-data" aria-label="Permalink to &quot;Mini-Program Data&quot;">​</a></h2><p>Mini-programs are community-provided rules that run in a sandboxed JavaScript engine. Any variables a rule stores (<code>setItem</code> / <code>getItem</code>) are kept in the app&#39;s local storage on your device. nPlyr does not read or transmit them.</p><h2 id="debug-logs" tabindex="-1">Debug Logs <a class="header-anchor" href="#debug-logs" aria-label="Permalink to &quot;Debug Logs&quot;">​</a></h2><p>If you enable debug logging, logs are written locally and are only shared if <em>you</em> choose to export them when reporting a problem.</p><h2 id="your-choices" tabindex="-1">Your Choices <a class="header-anchor" href="#your-choices" aria-label="Permalink to &quot;Your Choices&quot;">​</a></h2><ul><li>Delete individual history / bookmark / download entries at any time.</li><li>Reset all local data from <strong>Settings → Advanced → Reset</strong>.</li><li>Remove a mini-program and its stored variables from the <strong>Mini-Programs</strong> manager.</li></ul><p>nPlyr is built to be private by default — there is nothing to &quot;opt out&quot; of.</p>',17)])])}const m=a(t,[["render",n]]);export{p as __pageData,m as default};
